
--
--  Estrutura da tabela : CDIMAG
--

CREATE TABLE `CDIMAG` (
  `NUMERO` int NOT NULL AUTO_INCREMENT,
  `CODIGO_O` int DEFAULT '0',
  `CODIGO_D` int DEFAULT '0',
  `PRCNT_LC` float DEFAULT '0',
  `PRCNT_LCAN` float DEFAULT '0',
  `PRCNT_VN` float DEFAULT '0',
  `VALOR_LC` float DEFAULT '0',
  `VALOR_LCAN` float DEFAULT '0',
  `VALOR_VN` float DEFAULT '0',
  `VALOR_LC_N` float DEFAULT '0',
  `VALOR_LCAN_N` float DEFAULT '0',
  `VALOR_VN_N` float DEFAULT '0',
  `TIPO` varchar(30) DEFAULT 'Corretor',
  `DATA` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `TIPO_COMISSAO` varchar(5) DEFAULT NULL COMMENT '"%" ou "$"',
  `COMISSAO` decimal(10,2) DEFAULT NULL,
  `ID_MIGRACAO` varchar(50) DEFAULT NULL,
  UNIQUE KEY `NUMERO` (`NUMERO`),
  KEY `CODIGO_O` (`CODIGO_O`),
  KEY `CODIGO_D` (`CODIGO_D`)
) ENGINE=InnoDB AUTO_INCREMENT=4565 DEFAULT CHARSET=latin1 ;

